import SwiftUI

/// MUSE's one icon set: Phosphor Regular (plans/design-direction.md §5), drawn from the vendored template images in
/// Resources/Phosphor.xcassets (generated by design/icons/build.py).
///
/// `Ph("xmark", 14)` takes an SF Symbol name (mapped in design/icons/icons.txt) or a Phosphor name, and the point size
/// the old `.font(.system(size:))` gave the symbol. Phosphor draws inside a 256 box with padding, so the frame is a
/// little larger than the size to keep the visual weight. A name with no Phosphor match still draws its SF Symbol, so
/// an unmapped name is never blank.
struct Ph: View {
    let name: String
    var size: CGFloat

    init(_ name: String, _ size: CGFloat = 16) {
        self.name = name
        self.size = size
    }

    static func resolve(_ name: String) -> String? {
        PhosphorMap.sf[name] ?? (PhosphorMap.names.contains(name) ? name : nil)
    }

    var body: some View {
        if let p = Ph.resolve(name) {
            let side = (size * 1.25).rounded()
            Image("ph.\(p)")
                .renderingMode(.template)
                .resizable()
                .interpolation(.high)
                .aspectRatio(contentMode: .fit)
                .frame(width: side, height: side)
                .accessibilityHidden(true) // icon-only buttons carry their own label and .help
        } else {
            Image(systemName: name).font(.system(size: size))
        }
    }
}

extension Label where Title == Text, Icon == Ph {
    /// `Label("Reset all", ph: "arrow.counterclockwise")`: the text with a Phosphor icon in place of `systemImage:`.
    init(_ title: String, ph name: String, size: CGFloat = 13) {
        self.init { Text(title) } icon: { Ph(name, size) }
    }
}
